package com.aoo.bcg.common.invite;
import java.util.Set;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ShareLinkPolicyTest{@Test void rejectsDomainConfusionRedirectsAndProtocolInjection(){var policy=new ShareLinkPolicy(Set.of("share.aoo.example"));String token="abcdefghijklmnopqrstuvwxyz123456";assertEquals("share.aoo.example",policy.validate(policy.build("share.aoo.example",token).toString()).getHost());assertThrows(SecurityException.class,()->policy.validate("https://share.aoo.example.evil.test/invite/join?invite="+token));assertThrows(SecurityException.class,()->policy.validate("https://share.aoo.example@evil.test/invite/join?invite="+token));assertThrows(SecurityException.class,()->policy.validate("javascript://share.aoo.example/invite/join?invite="+token));assertThrows(SecurityException.class,()->policy.validate("https://share.aoo.example/invite/join?invite="+token+"&redirect=https://evil.test"));}}
